import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

// A league entry: a clickable category whose link is the generated landing page
// (docs/docs/{prefix}/index.md) and whose children are the auto-generated
// reference subtree (reference/{api}.md + loaders.md). The reference pages are
// regenerated from endpoint metadata by `python tools/codegen/generate.py --docs`
// and ordered/labelled via the generated _category_.json + page frontmatter, so
// new endpoints surface in the nav with no sidebar edit. Only adding a whole new
// LEAGUE needs a line here.
function league(prefix: string, label: string) {
  return {
    type: 'category' as const,
    label,
    link: {type: 'doc' as const, id: `${prefix}/index`},
    items: [{type: 'autogenerated' as const, dirName: `${prefix}/reference`}],
  };
}

const sidebars: SidebarsConfig = {
  // Single curated sidebar grouped by sport family (basketball / football / baseball /
  // hockey) so cross-league helpers cluster with the leagues that consume them.
  // Within each family pro leagues come first, then NCAA. The opening sections
  // (Architecture + Parsers + Parameter reference) cover package-wide patterns.
  docs: [
    {type: 'doc', id: 'intro', label: 'Getting Started'},
    {type: 'doc', id: 'ecosystem', label: 'Ecosystem & philosophy'},
    {type: 'doc', id: 'quality-of-life', label: 'Quality-of-life helpers'},
    {type: 'doc', id: 'architecture/espn-cross-league', label: 'How it works'},
    {type: 'doc', id: 'parsers/index', label: 'Parser layer'},
    {type: 'doc', id: 'reference/parameters', label: 'Parameter reference'},
    {
      type: 'category',
      label: 'Basketball',
      items: [
        league('nba', 'NBA'),
        league('wnba', 'WNBA'),
        league('mbb', 'MBB'),
        league('wbb', 'WBB'),
      ],
    },
    {
      type: 'category',
      label: 'Football',
      items: [
        league('nfl', 'NFL'),
        league('cfb', 'CFB'),
      ],
    },
    {
      type: 'category',
      label: 'Baseball',
      items: [league('mlb', 'MLB')],
    },
    {
      type: 'category',
      label: 'Hockey',
      items: [
        league('nhl', 'NHL'),
        league('pwhl', 'PWHL'),
      ],
    },
  ],
};

export default sidebars;
